package com.sathavahana.kalamkari.config;
import com.sathavahana.kalamkari.controller.NotFoundException; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.*;
@RestControllerAdvice public class RestExceptionHandler {record Error(Instant timestamp,int status,String error,String message,Map<String,String> fields){} @ExceptionHandler({NotFoundException.class,com.sathavahana.kalamkari.service.NotFoundException.class}) ResponseEntity<Error> notFound(RuntimeException e){return body(404,"Not Found",e.getMessage(),Map.of());} @ExceptionHandler(com.sathavahana.kalamkari.service.UnauthorizedException.class) ResponseEntity<Error> unauthorized(RuntimeException e){return body(401,"Unauthorized",e.getMessage(),Map.of());} @ExceptionHandler(com.sathavahana.kalamkari.service.ForbiddenException.class) ResponseEntity<Error> forbidden(RuntimeException e){return body(403,"Forbidden",e.getMessage(),Map.of());} @ExceptionHandler({IllegalArgumentException.class}) ResponseEntity<Error> bad(IllegalArgumentException e){return body(400,"Bad Request",e.getMessage(),Map.of());} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<Error> validation(MethodArgumentNotValidException e){var m=new HashMap<String,String>();e.getBindingResult().getFieldErrors().forEach(x->m.put(x.getField(),x.getDefaultMessage()));return body(400,"Validation failed","Request validation failed",m);} private ResponseEntity<Error> body(int s,String e,String m,Map<String,String> f){return ResponseEntity.status(s).body(new Error(Instant.now(),s,e,m,f));}}
